// One item per active watchlist row; the marketplace comes from the platform column or the URL
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; };
const yes = (v) => /^(yes|true|1|y)$/i.test(String(v ?? '').trim());
const out = [];
for (const { json: r } of $input.all()) {
  const url = String(r.url || '').trim();
  if (!url || /^(no|false|0|paused)$/i.test(String(r.active ?? '').trim())) continue;
  let platform = String(r.platform || '').trim().toLowerCase();
  if (!platform) platform = /amazon\./i.test(url) || /^B0[A-Z0-9]{8}$/.test(url) ? 'amazon' : /walmart\./i.test(url) ? 'walmart' : /ebay\./i.test(url) ? 'ebay' : '';
  if (!['amazon', 'walmart', 'ebay'].includes(platform)) continue;
  out.push({ json: {
    product: r.product || '',
    platform,
    url,
    our_price: num(r.our_price),
    watch_reviews: yes(r.watch_reviews),
    last_price: num(r.last_price),
    last_rating: num(r.last_rating),
    last_in_stock: r.last_in_stock === '' || r.last_in_stock == null ? null : yes(r.last_in_stock),
    last_units_sold: num(r.last_units_sold),
  } });
}
if (!out.length) throw new Error('No active products. Add Amazon, Walmart or eBay URLs to the Watchlist tab.');
return out;

// Reads each marketplace's own field names into one shape
const w = $('Loop over products').first().json;
const r = $input.first().json;
const num = (v) => { const n = typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; };
let p = {};
if (w.platform === 'amazon') {
  p = { title: r.title, price: num(r.price_value), list_price: num(r.list_price_value), currency: 'USD', availability: r.availability || '', in_stock: /in stock/i.test(r.availability || ''), rating: num(r.rating), review_count: num(r.rating_count), units_sold: null, seller: r.seller || '' };
} else if (w.platform === 'walmart') {
  const cur = (r.priceInfo && r.priceInfo.currentPrice) || {};
  p = { title: r.name, price: num(r.price ?? cur.price), list_price: num(r.was_price), currency: cur.currencyUnit || 'USD', availability: r.availabilityStatus || '', in_stock: r.availabilityStatus === 'IN_STOCK', rating: num(r.averageRating), review_count: num(r.numberOfReviews), units_sold: null, seller: (r.seller_info && r.seller_info.name) || r.sellerName || '' };
} else {
  p = { title: r.title, price: num(r.price_value), list_price: null, currency: r.currency || 'USD', availability: r.availability || '', in_stock: /instock/i.test(r.availability || ''), rating: num(r.rating), review_count: null, units_sold: num(r.quantity_sold), seller: (r.seller && r.seller.name) || '' };
}
const link = /^https?:\/\//.test(w.url) ? w.url : (r.url || w.url); // an Amazon row may hold a bare ASIN
return [{ json: { ...w, ...p, link, title: String(p.title || '').slice(0, 150), checked_at: new Date().toISOString() } }];

// A failed lookup becomes one marked item, so the loop carries on and the error is logged at the end
const w = $('Loop over products').first().json;
const err = $input.first().json.error || 'unknown error';
return [{ json: { _failed: true, product: w.product, platform: w.platform, url: w.url, error: String(err).slice(0, 300), at: new Date().toISOString() } }];

// Keeps the newest reviews at or under the star limit in Settings
const p = $('Normalise product').first().json;
const r = $input.first().json;
const max = Number($('Settings').first().json.low_star_max) || 2;
if (r.error) return [{ json: { ...p, low_star_reviews: [], review_note: `reviews not checked: ${String(r.error).slice(0, 150)}` } }];
const low = (r.reviews || [])
  .filter((x) => x.id && Number(x.rating) <= max)
  .map((x) => ({ review_id: `${p.platform}:${x.id}`, rating: Number(x.rating), title: x.title || '', text: String(x.text || '').slice(0, 500), date: x.date_iso || x.date || '', author: x.author || '' }));
return [{ json: { ...p, low_star_reviews: low, review_note: '' } }];

// Compares today's check with the values stored in the watchlist and the review log, and lists what changed
const s = $('Settings').first().json;
const dropPct = Number(s.price_drop_alert_pct) || 5;
const risePct = Number(s.price_rise_alert_pct) || 10;
const ratingDrop = Number(s.rating_drop_alert) || 0.1;
const knownReviews = new Set($input.all().map((i) => String(i.json.review_id || '')).filter(Boolean));
const round = (v) => Math.round(v * 10) / 10;
const out = [];
for (const { json: p } of $('Failed check?').all(1)) {
  const events = [];
  const change = p.price != null && p.last_price ? round(((p.price - p.last_price) / p.last_price) * 100) : null;
  if (p.price == null) {
    if (p.last_price != null) events.push(`no price shown (${p.availability || 'unavailable'})`);
  } else {
    if (change != null && change <= -dropPct) events.push(`price down ${Math.abs(change)}% (${p.last_price} → ${p.price})`);
    if (change != null && change >= risePct) events.push(`price up ${change}% (${p.last_price} → ${p.price})`);
    // alert once, when the competitor crosses under your price
    if (p.our_price != null && p.price < p.our_price && (p.last_price == null || p.last_price >= p.our_price)) events.push(`now under your price (${p.price} vs ${p.our_price})`);
  }
  if (p.last_in_stock === true && p.in_stock === false) events.push('went out of stock');
  if (p.last_in_stock === false && p.in_stock === true) events.push('back in stock');
  if (p.rating != null && p.last_rating != null && round(p.last_rating - p.rating) >= ratingDrop) events.push(`rating fell ${p.last_rating} → ${p.rating}`);
  const newReviews = (p.low_star_reviews || []).filter((r) => !knownReviews.has(r.review_id));
  if (newReviews.length) events.push(`${newReviews.length} new low-star review(s)`);
  const sold = p.units_sold != null && p.last_units_sold != null ? p.units_sold - p.last_units_sold : null;
  out.push({ json: {
    // watchlist columns (written back, matched on url)
    url: p.url,
    last_price: p.price ?? p.last_price ?? '',
    last_rating: p.rating ?? '',
    last_review_count: p.review_count ?? '',
    last_units_sold: p.units_sold ?? '',
    last_in_stock: p.in_stock,
    last_change_pct: change ?? '',
    last_checked: p.checked_at,
    status: events.length ? events.join('; ') : (p.review_note || 'no change'),
    // used by the history, review and alert steps
    _p: p,
    _change: change,
    _sold_since_last: sold,
    _events: events,
    _new_reviews: newReviews,
  } });
}
return out;

// One row per new low-star review; the review log is what keeps them from alerting twice
const now = new Date().toISOString();
const out = [];
for (const { json: c } of $input.all()) {
  for (const r of c._new_reviews) out.push({ json: { review_id: r.review_id, product: c._p.product, platform: c._p.platform, url: c._p.url, rating: r.rating, title: r.title, text: r.text, review_date: r.date, found_at: now } });
}
return out;

// One Slack message with every product that changed; nothing is sent on a quiet day
const changed = $input.all().map((i) => i.json).filter((c) => c._events.length);
if (!changed.length) return [];
const lines = changed.map((c) => {
  const p = c._p;
  const name = p.product || p.title;
  const reviews = c._new_reviews.slice(0, 2).map((r) => `\n      ${'★'.repeat(r.rating)} "${String(r.title || r.text).slice(0, 100)}"`).join('');
  return `• *${name}* on ${p.platform}: ${c._events.join(', ')} · <${p.link}|open>${reviews}`;
});
return [{ json: { text: `:rotating_light: *Competitor changes today* (${changed.length})\n${lines.join('\n')}` } }];

// Week-over-week view per product from the History tab
const since = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; };
const groups = new Map();
for (const { json: h } of $input.all()) {
  if (!h.url || String(h.date || '') < since) continue;
  if (!groups.has(h.url)) groups.set(h.url, []);
  groups.get(h.url).push(h);
}
if (!groups.size) return [{ json: { text: '*Weekly competitor digest:* no checks in the History tab for the last 7 days.' } }];
const rows = [];
for (const [url, list] of groups) {
  list.sort((a, b) => String(a.checked_at).localeCompare(String(b.checked_at)));
  const prices = list.map((h) => num(h.price)).filter((v) => v != null);
  const first = prices[0];
  const last = prices[prices.length - 1];
  const delta = first && last != null ? Math.round(((last - first) / first) * 1000) / 10 : null;
  const latest = list[list.length - 1];
  const our = num(latest.our_price);
  const outOfStock = list.filter((h) => String(h.in_stock).toLowerCase() === 'false').length;
  const lowReviews = list.reduce((n, h) => n + (num(h.new_low_reviews) || 0), 0);
  rows.push({ url: latest.link || url, name: latest.product || url, platform: latest.platform, last, min: prices.length ? Math.min(...prices) : null, max: prices.length ? Math.max(...prices) : null, delta, our, under: our != null && last != null && last < our, outOfStock, checks: list.length, lowReviews, rating: latest.rating });
}
rows.sort((a, b) => Math.abs(b.delta || 0) - Math.abs(a.delta || 0));
const fmt = (v) => (v == null || v === '' ? 'n/a' : Math.round(Number(v) * 100) / 100);
const lines = rows.map((r) => `• *${r.name}* (${r.platform}): ${fmt(r.last)} now, ${r.delta == null ? 'no price trend' : `${r.delta > 0 ? '+' : ''}${r.delta}% this week`} · range ${fmt(r.min)}-${fmt(r.max)}${r.under ? ` · :warning: under your ${r.our}` : ''}${r.outOfStock ? ` · out of stock on ${r.outOfStock}/${r.checks} checks` : ''}${r.lowReviews ? ` · ${r.lowReviews} new low-star review(s)` : ''} · rating ${fmt(r.rating)} · <${r.url}|open>`);
const under = rows.filter((r) => r.under).length;
return [{ json: { text: `:bar_chart: *Weekly competitor digest* (${rows.length} products, ${under} priced under yours)\n${lines.join('\n')}` } }];
